"use client"

import * as React from "react"

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { OrganisationIcon } from "@/components/design-system/icons"
import { AppShell } from "@/components/shell/app-shell"
import { ConversationsIndexPreview } from "@/components/design-system/conversations-index-preview"

const ORGANISATIONS = ["Sarj.ai", "Rawabi Holding", "Tamimi Markets"]

export function AdminViewSwitcher() {
  const [organisation, setOrganisation] = React.useState(ORGANISATIONS[0])

  return (
    <Select value={organisation} onValueChange={setOrganisation}>
      <SelectTrigger
        aria-label="Admin view"
        size="sm"
        className="border-warning/30 bg-warning-tint text-warning-tint-foreground"
      >
        <OrganisationIcon />
        <span className="font-medium">Admin view:</span>
        <SelectValue />
      </SelectTrigger>
      <SelectContent position="popper" align="end">
        {ORGANISATIONS.map((name) => (
          <SelectItem key={name} value={name}>
            {name}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  )
}

/** `translate-x-0` makes this frame the containing block for the app's fixed sidebar and drawers. */
export function AdminViewPagePreview() {
  return (
    <div className="relative flex h-180 translate-x-0 flex-col overflow-hidden rounded-xl border">
      <AppShell
        active="Conversations"
        scope={<AdminViewSwitcher />}
        underShell={false}
      >
        <ConversationsIndexPreview />
      </AppShell>
    </div>
  )
}

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { Card } from "@/components/ui/card"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from "@/components/ui/input-group"
import {
  AddFilter,
  ChoiceFilter,
  DateFilter,
  FilterBar,
  RangeFilter,
  SelectFilter,
  ToggleFilter,
  type Range,
  type DateRange,
} from "@/components/shared/filter-bar"
import { ListFooter } from "@/components/shared/list-footer"
import { PageHeader } from "@/components/shared/page-header"
import { CallTable } from "@/components/mockups/conversations-revamp/list/call-table"
import { FieldsDropdown } from "@/components/mockups/conversations-revamp/list/fields-dropdown"
import {
  ExportIcon,
  RefreshIcon,
  SearchIcon,
} from "@/components/mockups/conversations-revamp/list/icons"
import {
  CALLS,
  DEFAULT_COLUMNS,
  TOTAL_RESULTS,
  type CallRow,
} from "@/lib/mockups/conversations-revamp-list-data"

/** The day the mock calls were placed, so the date presets land on them. */
const TODAY = new Date(2026, 7, 11)

function label(value: string) {
  const words = value.replace(/_/g, " ")
  return words.charAt(0).toUpperCase() + words.slice(1)
}

function options(values: string[]) {
  return Array.from(new Set(values)).map((value) => ({
    value,
    label: label(value),
  }))
}

const STATUS_OPTIONS = options(CALLS.map((call) => call.status))
const OUTCOME_OPTIONS = options(CALLS.map((call) => call.outcome))
const SCENARIO_OPTIONS = Array.from(
  new Set(CALLS.map((call) => call.scenario)),
).map((scenario) => ({ value: scenario, label: scenario }))

const DIRECTION_OPTIONS = [
  { value: "inbound", label: "Inbound" },
  { value: "outbound", label: "Outbound" },
]

const MORE_FILTERS = [
  { id: "direction", label: "Direction" },
  { id: "duration", label: "Duration" },
  { id: "scheduled", label: "Scheduled only" },
]

const DURATION_PRESETS: Range[] = [{ max: 1 }, { min: 1, max: 5 }, { min: 5 }]

function minutes(duration: string) {
  const [m, s] = duration.split(":").map(Number)
  return (m || 0) + (s || 0) / 60
}

function inDuration(duration: string, range: Range | null) {
  if (!range) return true
  const value = minutes(duration)
  return (
    (range.min === undefined || value >= range.min) &&
    (range.max === undefined || value <= range.max)
  )
}

function inRange(stamp: string, range: DateRange | undefined) {
  if (!range?.from) return true
  const at = new Date(stamp.replace(/, (\d)/, " $1")).getTime()
  const from = new Date(range.from).setHours(0, 0, 0, 0)
  const to = new Date(range.to ?? range.from).setHours(23, 59, 59, 999)
  return at >= from && at <= to
}

export function ConversationsIndexPreview() {
  const [columns, setColumns] = React.useState(DEFAULT_COLUMNS)
  const [query, setQuery] = React.useState("")
  const [statuses, setStatuses] = React.useState<string[]>([])
  const [outcomes, setOutcomes] = React.useState<string[]>([])
  const [scenarios, setScenarios] = React.useState<string[]>([])
  const [date, setDate] = React.useState<DateRange | undefined>()
  const [direction, setDirection] = React.useState<string | null>(null)
  const [duration, setDuration] = React.useState<Range | null>(null)
  const [scheduledOnly, setScheduledOnly] = React.useState(false)
  const [added, setAdded] = React.useState<string[]>([])
  const [pageSize, setPageSize] = React.useState(25)

  const activeCount = [
    statuses.length,
    outcomes.length,
    scenarios.length,
    date?.from,
    direction,
    duration,
    scheduledOnly,
  ].filter(Boolean).length

  const digits = query.replace(/\D/g, "")
  const rows = CALLS.filter(
    (call: CallRow) =>
      (!digits ||
        (call.phoneNumber ?? "").replace(/\D/g, "").includes(digits)) &&
      (!statuses.length || statuses.includes(call.status)) &&
      (!outcomes.length || outcomes.includes(call.outcome)) &&
      (!scenarios.length || scenarios.includes(call.scenario)) &&
      inRange(call.createdAt, date) &&
      (!direction || call.direction === direction) &&
      inDuration(call.duration, duration) &&
      (!scheduledOnly || call.status === "scheduled"),
  )
  const total = activeCount || digits ? rows.length : TOTAL_RESULTS

  return (
    <div className="flex flex-1 flex-col gap-4 p-3 lg:p-4">
      <PageHeader title="Conversations" />

      <div className="flex flex-col gap-2">
        <div className="flex flex-wrap items-center gap-2">
          <InputGroup className="min-w-64 flex-1">
            <InputGroupAddon>
              <SearchIcon />
            </InputGroupAddon>
            <InputGroupInput
              aria-label="Search by phone number"
              placeholder="Search by phone number..."
              value={query}
              onChange={(event) => setQuery(event.target.value)}
            />
          </InputGroup>
          <Button aria-label="Refresh" size="icon" variant="outline">
            <RefreshIcon />
          </Button>
          <FieldsDropdown columns={columns} onChange={setColumns} />
          <Button variant="outline">
            <ExportIcon />
            Export
          </Button>
        </div>

        <FilterBar
          activeCount={activeCount}
          onClearAll={() => {
            setStatuses([])
            setOutcomes([])
            setScenarios([])
            setDate(undefined)
            setDirection(null)
            setDuration(null)
            setScheduledOnly(false)
          }}
        >
          <SelectFilter
            field="Status"
            options={STATUS_OPTIONS}
            value={statuses}
            onChange={setStatuses}
          />
          <SelectFilter
            field="Outcome"
            options={OUTCOME_OPTIONS}
            value={outcomes}
            onChange={setOutcomes}
          />
          <DateFilter
            field="Date"
            value={date}
            onChange={setDate}
            today={TODAY}
          />
          <SelectFilter
            field="Scenario"
            options={SCENARIO_OPTIONS}
            value={scenarios}
            onChange={setScenarios}
          />
          {added.includes("direction") ? (
            <ChoiceFilter
              field="Direction"
              options={DIRECTION_OPTIONS}
              value={direction}
              onChange={setDirection}
            />
          ) : null}
          {added.includes("duration") ? (
            <RangeFilter
              field="Duration"
              unit="min"
              presets={DURATION_PRESETS}
              value={duration}
              onChange={setDuration}
            />
          ) : null}
          {added.includes("scheduled") ? (
            <ToggleFilter
              field="Scheduled only"
              value={scheduledOnly}
              onChange={setScheduledOnly}
            />
          ) : null}
          <AddFilter
            fields={MORE_FILTERS.filter((field) => !added.includes(field.id))}
            onAdd={(id) => setAdded((list) => [...list, id])}
          />
        </FilterBar>
      </div>

      <Card className="[--card-spacing:0px]">
        <div className="overflow-x-auto">
          <CallTable calls={rows} columns={columns} onCallClick={() => {}} />
        </div>
      </Card>

      <ListFooter
        from={1}
        shown={rows.length}
        total={total}
        noun="calls"
        pageSize={pageSize}
        onPageSizeChange={setPageSize}
        atStart
        atEnd={rows.length >= total}
      />
    </div>
  )
}

